@Test
public void testCursorPosition() {
    Paragraph paragraph = spy(new Paragraph());
    // left = buffer, middle = cursor position into source code, right = cursor position after parse
    List<Triple<String, Integer, Integer>> dataSet = Arrays.asList(Triple.of("%jdbc schema.", 13, 7), Triple.of("   %jdbc schema.", 16, 7), Triple.of(" 
%jdbc schema.", 15, 7), Triple.of("%jdbc schema.table.  ", 19, 13), Triple.of("%jdbc schema.

", 13, 7), Triple.of("  %jdbc schema.tab

", 18, 10), Triple.of("  
%jdbc schema.

", 16, 7), Triple.of("  
%jdbc schema.

", 16, 7), Triple.of("  
%jdbc

 schema

", 17, 6), Triple.of("%another

 schema.", 18, 7), Triple.of("

 schema.", 10, 7), Triple.of("schema.", 7, 7), Triple.of("schema. 
", 7, 7), Triple.of("  
   %jdbc", 11, 0), Triple.of("
   %jdbc", 9, 0), Triple.of("%jdbc  
  schema", 16, 6), Triple.of("%jdbc  

   schema", 20, 6));
    for (Triple<String, Integer, Integer> data : dataSet) {
        paragraph.setText(data.getLeft());
        Integer actual = paragraph.calculateCursorPosition(data.getLeft(), data.getMiddle());
        assertEquals(data.getRight(), actual);
    }
}

